require __DIR__.'/includes/bootstrap.php';header('Content-Type: application/xml; charset=utf-8');echo '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">';
foreach(['','about.php','privacy.php','terms.php','contact.php','affiliate-disclosure.php','audio','asmr-guides/','asmr-triggers/','sleep-sounds/','focus-relaxation/','asmr-equipment/','asmr-creators/'] as $path)echo '<url><loc>'.e(url($path)).'</loc></url>';
if($pdo){try{$q=$pdo->query("SELECT slug,category,featured_image,updated_at FROM articles WHERE status='published' AND noindex=0");foreach($q as $r){$category=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$r['category']??''),'-'));echo '<url><loc>'.e(url(($category?$category.'/':'').$r['slug'].'/')).'</loc><lastmod>'.date('c',strtotime($r['updated_at'])).'</lastmod>';if($r['featured_image'])echo '<image:image><image:loc>'.e(url('uploads/'.$r['featured_image'])).'</image:loc></image:image>';echo '</url>';}}catch(Throwable $e){}foreach([['audio_tracks','audio/','cover_image'],['creators','creators/','profile_image'],['products','products/','image']] as [$table,$prefix,$image]){try{$q=$pdo->query("SELECT slug,updated_at,$image AS image FROM $table WHERE status='published'");foreach($q as $r){echo '<url><loc>'.e(url($prefix.$r['slug'].'/')).'</loc><lastmod>'.date('c',strtotime($r['updated_at'])).'</lastmod>';if($r['image'])echo '<image:image><image:loc>'.e(url('uploads/'.$r['image'])).'</image:loc></image:image>';echo '</url>';}}catch(Throwable $e){}}}
